
const LK="data:image/png;base64,",LW="data:image/png;base64,";
const root=document.documentElement,tg=document.getElementById('tg'),top_=document.getElementById('lg-top');
document.querySelectorAll('[data-w]').forEach(i=>i.src=LW);
function theme(t,save){root.dataset.theme=t;top_.src=t==='dark'?LW:LK;tg.setAttribute('aria-pressed',t==='dark');
if(save){try{localStorage.setItem('pua-theme',t)}catch(e){}}}
let st=null;try{st=localStorage.getItem('pua-theme')}catch(e){}
theme(st==='dark'?'dark':'light');
tg.onclick=()=>theme(root.dataset.theme==='dark'?'light':'dark',true);
const ic={
ig:'<path d="M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5zm0 2a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3H7zm5 3.5a4.5 4.5 0 1 1 0 9 4.5 4.5 0 0 1 0-9zm0 2a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5zM17.6 5.4a1.1 1.1 0 1 1 0 2.2 1.1 1.1 0 0 1 0-2.2z"/>',
tt:'<path d="M16 3c.3 2.4 1.8 4 4 4.2v3.1c-1.500 0-2.900-.4-4-1.200V16a6 6 0 1 1-6-6c.3 0 .7 0 1 .1v3.200a2.900 2.900 0 1 0 2 2.700V3h3z"/>',
yt:'<path d="M21.600 7.200a2.500 2.500 0 0 0-1.800-1.800C18.200 5 12 5 12 5s-6.200 0-7.800.4A2.500 2.500 0 0 0 2.400 7.200C2 8.800 2 12 2 12s0 3.200.4 4.800a2.500 2.500 0 0 0 1.800 1.800C5.800 19 12 19 12 19s6.200 0 7.800-.4a2.500 2.500 0 0 0 1.800-1.800c.4-1.600.4-4.800.4-4.800s0-3.200-.4-4.800zM10 15V9l5.200 3L10 15z"/>'};
const a=(k,l,h)=>`<a href="${h}" target="_blank" rel="noopener" aria-label="${l}"><svg viewBox="0 0 24 24">${ic[k]}</svg></a>`;
const ch=a('ig','Instagram da Casa do Hip-Hop','#'),dc=a('ig','Instagram da Discovery','#')+a('tt','TikTok da Discovery','#')+a('yt','YouTube da Discovery','#');
document.getElementById('soc-top').innerHTML=ch+dc;
document.getElementById('soc-ch').innerHTML=ch;document.getElementById('soc-dc').innerHTML=dc;
const words=['Um gesto hoje','Por um amanhã','Discovery New Ways','Stem Racing','Casa do Hip-Hop','Piracicaba'];
const m=words.map(w=>`<span>${w}</span><span>●</span>`).join('');document.getElementById('mq').innerHTML=m+m+m+m;

const tabs=[...document.querySelectorAll('nav button')],ids=['quem-somos','o-que-e','o-projeto'];
function show(id,push){if(!ids.includes(id))id='quem-somos';
document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('on',p.id===id));
tabs.forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===id));
if(push&&location.hash!=='#'+id)history.replaceState(null,'','#'+id)}
document.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();show(el.dataset.tab,true);
const t=el.closest('.hero')||el.tagName==='BUTTON'?document.querySelector('.strip'):null;
document.querySelector('.strip').scrollIntoView({behavior:'smooth',block:'start'})}));
addEventListener('hashchange',()=>show(location.hash.slice(1)));
show(location.hash.slice(1));

const f=document.getElementById('form'),hint=document.getElementById('hint');
f.addEventListener('change',()=>hint.classList.toggle('on',f.tipo.value!=='Dinheiro (PIX)'));
f.addEventListener('submit',e=>{e.preventDefault();const n=nome.value.trim(),t=tel.value.trim(),em=mail.value.trim(),err=document.getElementById('err');
if(!n||t.replace(/\D/g,'').length<10||!/^\S+@\S+\.\S+$/.test(em)){err.textContent='Preencha nome completo, telefone com DDD e um e-mail válido.';return}
err.textContent='';const tp=f.tipo.value;
document.getElementById('who').textContent=n.split(' ')[0];
document.getElementById('okmsg').textContent=tp==='Dinheiro (PIX)'?'Recebemos seu interesse em apadrinhar com PIX. A Casa do HIP-HOP entrará em contato pelos dados informados.':'Recebemos seu interesse em doar '+(tp==='Ração'?'ração':'uma cesta básica')+'. Lembre-se de entregar pessoalmente na Rua Jaçanã Altair Pereira Guerrine, 200, Paulicéia.';
document.getElementById('fbody').style.display='none';document.getElementById('ok').classList.add('on')});
document.getElementById('again').onclick=()=>{f.reset();hint.classList.remove('on');document.getElementById('fbody').style.display='';document.getElementById('ok').classList.remove('on')};
